/**
 * frontend/vite.config.ts
 *
 * PURPOSE
 *   Vite dev server + build configuration (generated by the react-ts template).
 *
 * SHOULD CONTAIN
 *   - The React plugin.
 *   - (Optional, recommended) a dev-server proxy so "/api/..." forwards to the FastAPI server on port 8000.
 *     The browser then sees same-origin requests (no CORS in dev), and api.ts can use relative URLs.
 *     If you skip the proxy, configure CORS in backend/app/main.py instead (you'll do that anyway, to learn it).
 *
 * AVOID: hardcoding the backend URL in components. It belongs here or in one constant in api.ts.
 */
